// Historical fixtures are generated by validation/strategy33_parity_review.py.
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import vm from 'node:vm';
import {parseYaml} from '../../data-proxy/src/strategy-runtime.js';

const root = new URL('../../', import.meta.url);
const browser = readFileSync(new URL('src/web/app.js', root), 'utf8');
const worker = readFileSync(new URL('data-proxy/src/strategy-runtime.js', root), 'utf8');
const browserCore = browser.slice(browser.indexOf('function pct('), browser.indexOf('function resolve(def, all)'));
const contexts = [
  ['browser', browserCore],
  ['worker', worker.replace(/^export /gm, '')],
].map(([name, code]) => {
  const context = vm.createContext({});
  vm.runInContext(`${code}\nglobalThis.Runtime=Declarative;globalThis.periodKey=period;`, context);
  return [name, context];
});
const yaml = parseYaml(readFileSync(new URL('strategies/33_qqq_guarded_reentry_buy_acceleration.yaml', root), 'utf8'));
const retirement = parseYaml(readFileSync(new URL('strategies/31_band_7030_tdf_valuation_credit_guard_no_topup.yaml', root), 'utf8'));
const cases = ['current', 'dotcom_proxy', 'gfc_proxy'].map(period => ({
  period, yaml, file: `strategy33/${period}_fixture.json`,
}));
for (const [period, proxies] of (process.argv.includes('--retirement') ? [['current', ['actual_components']], ['dotcom_proxy', ['spy', 'qqq']], ['gfc_proxy', ['spy', 'qqq']]] : []))
  for (const proxy of proxies) cases.push({period: `31 ${period} ${proxy}`, yaml: retirement,
    file: `strategy31_reentry/reentry_only/${period}_${proxy}_main_v3_fixture.json`});
const normalized = value => typeof value === 'string' ? value.trim().replace(/\s+/g, ' ')
  : Array.isArray(value) ? value.map(normalized)
  : value && typeof value === 'object' ? Object.fromEntries(Object.entries(value).map(([key, item]) => [key, normalized(item)])) : value;
for (const [name, context] of contexts) {
  assert.equal(context.periodKey('2020-12-31', 'weekly'), context.periodKey('2021-01-01', 'weekly'), name);
  assert.equal(context.periodKey('2021-01-04', 'weekly'), context.periodKey('2021-01-08', 'weekly'), name);
  assert.notEqual(context.periodKey('2021-01-08', 'weekly'), context.periodKey('2021-01-11', 'weekly'), name);
  for (const {period, yaml: chosen, file} of cases) {
    const fixture = JSON.parse(readFileSync(new URL(`results/research/qqq/${file}`, root), 'utf8'));
    const def = structuredClone(chosen);
    def.parameters = fixture.definition.parameters;
    // The selected retirement variant omits the unused BUY diagnostic counter.
    if (period.startsWith('31 ')) {
      delete fixture.definition.state.recovery_turn_days;
      for (const row of fixture.rows) delete row.state.recovery_turn_days;
      fixture.definition.strategy.name = def.strategy.name;
    }
    assert.deepEqual(normalized(def), normalized(fixture.definition), 'Worker YAML parser must reproduce Python definition');
    const runtime = new context.Runtime(def);
    for (const row of fixture.rows) {
      const market = Object.fromEntries(Object.entries(row.market).map(([ticker, values]) => [ticker,
        Object.fromEntries(Object.entries(values).map(([key, value]) => [key.toLowerCase(), value === null ? NaN : value]))]));
      const signal = runtime.step(row.date, market, {weights: () => row.weights});
      const where = `${name} ${period} ${row.date}`;
      for (const [ticker, expected] of Object.entries(row.target))
        assert.ok(Math.abs(signal.target[ticker] - expected) < 1e-10, `${where} target ${ticker}`);
      assert.equal(signal.rebalance, row.rebalance, `${where} rebalance`);
      for (const [key, expected] of Object.entries(row.state)) {
        if (typeof expected === 'number') assert.ok(Math.abs(runtime.state[key] - expected) < 1e-9, `${where} ${key}`);
        else assert.equal(runtime.state[key], expected, `${where} ${key}`);
      }
    }
    console.log(`${name} ${period}: ${fixture.rows.length} daily states, targets and rebalance signals matched`);
  }
}
